CREATE TABLE "proposal_submissions"("id" UUID PRIMARY KEY,"proposalId" UUID NOT NULL,"proposalVersionId" UUID NOT NULL UNIQUE,"commercialScenarioId" UUID NOT NULL,"payload" JSONB NOT NULL,"payloadHash" CHAR(64) NOT NULL,"channel" VARCHAR(160) NOT NULL,"submittedAt" TIMESTAMPTZ(6) NOT NULL,"protocol" VARCHAR(200) NOT NULL,"evidenceDocumentVersionId" UUID NOT NULL,"evidenceFileHash" CHAR(64) NOT NULL,"submittedBy" UUID NOT NULL,"correlationId" UUID NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "proposal_submission_proposal_fkey" FOREIGN KEY("proposalId") REFERENCES "proposals"("id") ON DELETE RESTRICT,CONSTRAINT "proposal_submission_version_fkey" FOREIGN KEY("proposalVersionId") REFERENCES "proposal_versions"("id") ON DELETE RESTRICT,CONSTRAINT "proposal_submission_scenario_fkey" FOREIGN KEY("commercialScenarioId") REFERENCES "commercial_scenarios"("id") ON DELETE RESTRICT,CONSTRAINT "proposal_submission_evidence_fkey" FOREIGN KEY("evidenceDocumentVersionId") REFERENCES "managed_document_versions"("id") ON DELETE RESTRICT,CONSTRAINT "proposal_submission_user_fkey" FOREIGN KEY("submittedBy") REFERENCES "users"("id") ON DELETE RESTRICT,CONSTRAINT "proposal_submission_protocol_unique" UNIQUE("channel","protocol"),CONSTRAINT "proposal_submission_channel" CHECK(length(btrim("channel"))>=2),CONSTRAINT "proposal_submission_protocol" CHECK(length(btrim("protocol"))>=3));CREATE INDEX "proposal_submission_proposal_idx" ON "proposal_submissions"("proposalId","submittedAt");CREATE INDEX "proposal_submission_hash_idx" ON "proposal_submissions"("payloadHash");CREATE INDEX "proposal_submission_correlation_idx" ON "proposal_submissions"("correlationId");
CREATE FUNCTION "validate_proposal_submission"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE proposal_version RECORD;scenario_component UUID;document_hash CHAR(64);technical_pending INTEGER;BEGIN SELECT "proposalId","version" INTO proposal_version FROM "proposal_versions" WHERE "id"=NEW."proposalVersionId";IF proposal_version."proposalId" IS DISTINCT FROM NEW."proposalId" THEN RAISE EXCEPTION 'proposal version mismatch';END IF;IF NOT EXISTS(SELECT 1 FROM "proposals" WHERE "id"=NEW."proposalId" AND "version"=proposal_version."version" AND "status"<>'SENT') THEN RAISE EXCEPTION 'submission requires current unsent proposal version';END IF;SELECT component."proposalVersionId" INTO scenario_component FROM "commercial_scenarios" scenario JOIN "proposal_components" component ON component."id"=scenario."componentId" WHERE scenario."id"=NEW."commercialScenarioId";IF scenario_component IS DISTINCT FROM NEW."proposalVersionId" THEN RAISE EXCEPTION 'commercial scenario must belong to proposal version';END IF;IF NOT EXISTS(SELECT 1 FROM "commercial_approvals" WHERE "scenarioId"=NEW."commercialScenarioId" AND "decision"='APPROVED') THEN RAISE EXCEPTION 'approved commercial scenario required';END IF;SELECT count(*) INTO technical_pending FROM "proposal_technical_sections" section JOIN "proposal_components" component ON component."id"=section."componentId" WHERE component."proposalVersionId"=NEW."proposalVersionId" AND section."status"<>'COMPLETED';IF technical_pending>0 OR NOT EXISTS(SELECT 1 FROM "proposal_technical_sections" section JOIN "proposal_components" component ON component."id"=section."componentId" WHERE component."proposalVersionId"=NEW."proposalVersionId") THEN RAISE EXCEPTION 'all technical sections must be completed';END IF;SELECT "fileHash" INTO document_hash FROM "managed_document_versions" WHERE "id"=NEW."evidenceDocumentVersionId";IF document_hash IS DISTINCT FROM NEW."evidenceFileHash" THEN RAISE EXCEPTION 'submission evidence hash mismatch';END IF;RETURN NEW;END $$;CREATE TRIGGER "proposal_submission_guard" BEFORE INSERT ON "proposal_submissions" FOR EACH ROW EXECUTE FUNCTION "validate_proposal_submission"();
CREATE FUNCTION "complete_proposal_submission"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE "proposals" SET "status"='SENT',"updatedAt"=CURRENT_TIMESTAMP,"updatedBy"=NEW."submittedBy" WHERE "id"=NEW."proposalId";UPDATE "proposal_components" SET "status"='APPROVED' WHERE "proposalVersionId"=NEW."proposalVersionId";RETURN NEW;END $$;CREATE TRIGGER "proposal_submission_complete" AFTER INSERT ON "proposal_submissions" FOR EACH ROW EXECUTE FUNCTION "complete_proposal_submission"();
CREATE FUNCTION "reject_proposal_submission_mutation"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'proposal submissions are immutable';END $$;CREATE TRIGGER "proposal_submission_append_only" BEFORE UPDATE OR DELETE ON "proposal_submissions" FOR EACH ROW EXECUTE FUNCTION "reject_proposal_submission_mutation"();
